import json,re
from pathlib import Path
base=Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts')
ids=['061e7f65-b85e-4bfa-8894-11327f471920','6c683072-3ae0-462a-ad02-bb5409e2479a','7a815262-2440-4986-8173-2515ea7ec180','098583b3-32d8-480e-873d-afe02aa18184','48dd9295-cbde-4984-aeb4-26a130b521d8','d9e8abc0-80df-4d35-bbb4-ac53d307286e']
for tid in ids:
    p=base/tid/f'{tid}.jsonl'
    if not p.exists():
        print('MISSING', tid); continue
    print('\n====', tid, '====')
    users=[]; finals=[]
    for line in p.open():
        try: o=json.loads(line)
        except: continue
        role=o.get('role') or o.get('type') or ''
        # cursor format varies
        if 'message' in o:
            m=o['message']; role=m.get('role',role); content=m.get('content')
        else:
            content=o.get('content') or o.get('text')
        text=''
        if isinstance(content,str): text=content
        elif isinstance(content,list):
            parts=[]
            for c in content:
                if isinstance(c,str): parts.append(c)
                elif isinstance(c,dict):
                    if c.get('type') in ('text','input_text','output_text'): parts.append(c.get('text') or '')
            text='\n'.join(parts)
        if not text: continue
        if role in ('user','human'):
            # skip system wakes that are huge
            t=text.strip()
            if t.startswith('<') and 'user_query' in t:
                m=re.search(r'<user_query>\s*(.*?)\s*</user_query>', t, re.S)
                if m: t=m.group(1).strip()
            if len(t)>20:
                users.append(t[:200].replace('\n',' '))
        elif role in ('assistant',):
            # keep shorter final-ish replies
            if len(text)<1200 and not text.startswith('{') and 'function_call' not in text[:50]:
                finals.append(text[:350].replace('\n',' '))
    print('USER:', users[0] if users else '(none)')
    for u in users[1:4]:
        print('USER+', u[:180])
    print('ASST_LAST:', finals[-1] if finals else '(none)')
    if len(finals)>1: print('ASST_PREV:', finals[-2][:250])
